          "code": "import numpy as np\n\nrng = np.random.default_rng(144)\n\n# 1. Bukti Empiris Union Bound: Probabilitas Sampel Tanpa Pohon OOB Saat B Kecil\nn = 400\np_in_bag = 1.0 - (1.0 - 1.0 / n) ** n\nprint(\"=== 1. Cakupan Sampel OOB & Risiko Baris Tanpa Pohon OOB Saat B Kecil (n=400) ===\")\nprint(\"Jumlah Pohon B | E[Pohon OOB/baris] | Teori P(ada baris 0 OOB) | Baris Tanpa OOB (Empiris)\")\nprint(\"-\" * 92)\nfor B in [5, 10, 20, 40, 100]:\n    boots = rng.integers(0, n, size=(B, n))\n    oob_counts = np.zeros(n, dtype=int)\n    for b in range(B):\n        in_bag = np.zeros(n, dtype=bool)\n        in_bag[boots[b]] = True\n        oob_counts += (~in_bag).astype(int)\n    zero_rows = int(np.sum(oob_counts == 0))\n    # Probabilitas eksak >= 1 baris tak pernah jadi OOB (aproksimasi independen): 1 - (1 - p_in_bag^B)^n\n    p_miss_any = 1.0 - (1.0 - (p_in_bag ** B)) ** n\n    print(f\"{B:14d} | {float(np.mean(oob_counts)):18.2f} | {p_miss_any:24.6f} | {zero_rows:25d}\")\n\n# 2. Bukti Geurts (2006) Teorema 1: Efek Smoothing Linear dari Random Cut-Point Extra-Trees\n# Dua titik tetangga: (x_L=0.0, y_L=2.0) dan (x_R=4.0, y_R=10.0) -> interpolasi linier eksak y(x) = 2 + 2x\nx_L, y_L = 0.0, 2.0\nx_R, y_R = 4.0, 10.0\nx_grid = np.array([0.5, 1.0, 1.5, 2.0, 2.5, 3.0, 3.5])\ny_linear_exact = y_L + (y_R - y_L) * (x_grid - x_L) / (x_R - x_L)\n\n# CART / Random Forest standar: selalu memotong di titik tengah (x_L + x_R)/2 = 2.0 -> fungsi tangga patah!\ncart_mid = 0.5 * (x_L + x_R)\ny_cart_step = np.where(x_grid <= cart_mid, y_L, y_R)\n\n# Extra-Trees: tarik B=2000 cut-point acak s ~ Uniform(x_L, x_R) lalu rata-ratakan prediksi\ncuts = rng.uniform(x_L, x_R, size=2000)\n# Untuk setiap x, pohon memprediksi y_L jika x <= s, selain itu y_R\net_preds = np.where(x_grid[None, :] <= cuts[:, None], y_L, y_R).mean(axis=0)\n\nprint(\"\\n=== 2. Bukti Teorema Smoothing Geurts (2006): CART Step-Function vs Extra-Trees ===\")\nprint(\"x_query | Interpolasi Linier Eksak | CART (Midpoint) | Extra-Trees (B=2000) | |ET - Linier|\")\nprint(\"-\" * 92)\nfor xv, yl, yc, ye in zip(x_grid, y_linear_exact, y_cart_step, et_preds):\n    print(f\"{xv:7.2f} | {yl:24.4f} | {yc:15.4f} | {ye:20.4f} | {abs(ye - yl):13.4f}\")",
