          "id": "code-ml-14-3-ch14_3_scratch",
          "title": "First-Principles NumPy + rf.apply(X): Implementasi Penuh QRF (Meinshausen 2006), CDF & Pinball Loss",
          "language": "python",
          "filename": "14_3_qrf_meinshausen_apply_scratch.py",
          "code": "import numpy as np\nfrom sklearn.ensemble import RandomForestRegressor\n\nclass QuantileRegressionForestScratch:\n    \"\"\"Implementasi Meinshausen (2006) QRF dari nol di atas rf.apply(X) + bobot daun empiris.\"\"\"\n\n    def __init__(self, n_estimators: int = 120, min_samples_leaf: int = 8, max_features: float = 0.7, random_state: int = 42):\n        self.rf = RandomForestRegressor(\n            n_estimators=n_estimators,\n            min_samples_leaf=min_samples_leaf,\n            max_features=max_features,\n            bootstrap=False,  # 100% sampel latih terpetakan eksak ke daun sehingga mean QRF == mean RF\n            random_state=random_state,\n            n_jobs=1,\n        )\n\n    def fit(self, X: np.ndarray, y: np.ndarray) -> \"QuantileRegressionForestScratch\":\n        self.rf.fit(X, y)\n        # Simpan y_train terurut menaik & leaf ID tiap baris latih pada seluruh B pohon\n        order = np.argsort(y)\n        self.y_sorted_ = y[order].astype(float)\n        self.train_leaves_ = self.rf.apply(X[order])  # bentuk (n_train, B)\n        return self\n\n    def predict_quantiles_and_mean(self, X: np.ndarray, quantiles: list[float]) -> tuple[np.ndarray, np.ndarray, float]:\n        query_leaves = self.rf.apply(X)  # bentuk (n_query, B)\n        n_q, B = query_leaves.shape\n        n_tr = len(self.y_sorted_)\n        q_out = np.zeros((n_q, len(quantiles)), dtype=float)\n        w_mean = np.zeros(n_q, dtype=float)\n        max_sum_err = 0.0\n\n        for j in range(n_q):\n            # Cocokkan leaf ID titik uji j terhadap seluruh baris latih di semua B pohon sekaligus\n            matches = (self.train_leaves_ == query_leaves[j][None, :])  # (n_tr, B)\n            leaf_sizes = matches.sum(axis=0, keepdims=True)             # (1, B)\n            # Bobot Meinshausen w_i(x) = (1/B) sum_b I(x_i in R_b(x)) / |R_b(x)|\n            weights = np.mean(matches / leaf_sizes, axis=1)             # (n_tr,)\n            max_sum_err = max(max_sum_err, abs(float(np.sum(weights)) - 1.0))\n            w_mean[j] = float(weights @ self.y_sorted_)\n            cdf = np.cumsum(weights)\n            for qi, alpha in enumerate(quantiles):\n                idx = int(np.searchsorted(cdf, alpha, side=\"left\"))\n                q_out[j, qi] = self.y_sorted_[min(idx, n_tr - 1)]\n        return q_out, w_mean, max_sum_err\n\n\ndef pinball_loss(y: np.ndarray, q_hat: np.ndarray, alpha: float) -> float:\n    diff = y - q_hat\n    return float(np.mean(np.maximum(alpha * diff, (alpha - 1.0) * diff)))\n\n\n# Bangkitkan data ETA pengiriman heteroskedastik + right-skewed (Log-Normal bertambah lebar saat x0 naik!)\nrng = np.random.default_rng(147)\ndef make_eta(n: int):\n    X = rng.uniform(0.0, 1.0, size=(n, 4))\n    base_mu = 20.0 + 35.0 * X[:, 0] + 10.0 * X[:, 1]\n    # Saat hujan/macet (x0 mendekati 1), dispersi lonjakan delay meledak 5x dan miring ke kanan!\n    sigma_log = 0.12 + 0.50 * (X[:, 0] ** 1.5)\n    delay = np.exp(rng.normal(0.0, sigma_log)) * (4.0 + 18.0 * X[:, 0])\n    y = base_mu + delay\n    return X, y\n\nX_tr, y_tr = make_eta(800)\nX_te, y_te = make_eta(400)\n\nqrf = QuantileRegressionForestScratch(n_estimators=100, min_samples_leaf=10, max_features=0.75, random_state=42).fit(X_tr, y_tr)\nqs, w_mean, sum_err = qrf.predict_quantiles_and_mean(X_te, [0.10, 0.50, 0.90])\nrf_mean = qrf.rf.predict(X_te)\n\np10, p50, p90 = qs[:, 0], qs[:, 1], qs[:, 2]\ncov_80 = float(np.mean((y_te >= p10) & (y_te <= p90)))\ncrossings = int(np.sum((p10 > p50) | (p50 > p90)))\ncalm = X_te[:, 0] < 0.30\nstorm = X_te[:, 0] > 0.70\n\nprint(\"=== Verifikasi First-Principles Quantile Regression Forest (Meinshausen 2006) ===\")\nprint(f\"Max galat simpleks |sum_i w_i(x) - 1|       : {sum_err:.2e}\")\nprint(f\"Max |Mean Bobot QRF - rf.predict(X)|        : {float(np.max(np.abs(w_mean - rf_mean))):.2e}\")\nprint(f\"Jumlah Quantile Crossing (P10>P50 / P50>P90): {crossings} (DIJAMIN 0 secara matematis!)\")\nprint(f\"Empirical Coverage P10-P90 (Target = 80.0%) : {cov_80 * 100:.2f}%\")\nprint(f\"Pinball Loss P10 / P50 / P90                : {pinball_loss(y_te, p10, 0.1):.3f} / {pinball_loss(y_te, p50, 0.5):.3f} / {pinball_loss(y_te, p90, 0.9):.3f}\")\nprint(\"-\" * 80)\nprint(f\"Zona Tenang (x0<0.3) -> Lebar P90-P10: {float(np.mean(p90[calm]-p10[calm])):6.2f} mnt | Asimetri (P90-P50)/(P50-P10): {float(np.mean((p90[calm]-p50[calm])/np.maximum(p50[calm]-p10[calm], 1e-6))):.2f}\")\nprint(f\"Zona Badai  (x0>0.7) -> Lebar P90-P10: {float(np.mean(p90[storm]-p10[storm])):6.2f} mnt | Asimetri (P90-P50)/(P50-P10): {float(np.mean((p90[storm]-p50[storm])/np.maximum(p50[storm]-p10[storm], 1e-6))):.2f}\")",
          "expectedOutput": "=== Verifikasi First-Principles Quantile Regression Forest (Meinshausen 2006) ===\nMax galat simpleks |sum_i w_i(x) - 1|       : 7.77e-16\nMax |Mean Bobot QRF - rf.predict(X)|        : 1.28e-13\nJumlah Quantile Crossing (P10>P50 / P50>P90): 0 (DIJAMIN 0 secara matematis!)\nEmpirical Coverage P10-P90 (Target = 80.0%) : 80.00%\nPinball Loss P10 / P50 / P90                : 0.819 / 2.339 / 1.523\n--------------------------------------------------------------------------------\nZona Tenang (x0<0.3) -> Lebar P90-P10:   4.96 mnt | Asimetri (P90-P50)/(P50-P10): 1.32\nZona Badai  (x0>0.7) -> Lebar P90-P10:  27.59 mnt | Asimetri (P90-P50)/(P50-P10): 2.05",
