          "id": "code-ml-14-4-ch14_4_sklearn",
          "title": "Scikit-Learn: MDI vs Train-Permutation (Jebakan!) vs Held-Out Val-Permutation pada Noise random_uuid",
          "language": "python",
          "filename": "14_4_sklearn_mdi_vs_train_vs_val_perm.py",
          "code": "import numpy as np\nfrom sklearn.ensemble import RandomForestClassifier\nfrom sklearn.inspection import permutation_importance\nfrom sklearn.metrics import roc_auc_score\nfrom sklearn.model_selection import train_test_split\n\nrng = np.random.default_rng(151)\nn = 1200\n\n# 2 fitur sinyal asli (1 biner kardinalitas rendah + 1 kontinu sedang) + 2 fitur NOISE murni ber-kardinalitas tinggi!\nis_high_risk_bin = rng.binomial(1, 0.25, size=n).astype(float)\ntxn_velocity = rng.normal(0.0, 1.0, size=n)\nrandom_noise_float = rng.normal(0.0, 1.0, size=n)\nrandom_uuid_int = rng.integers(100_000, 999_999, size=n).astype(float)\n\nlogits = -1.1 + 1.45 * is_high_risk_bin + 0.85 * txn_velocity + rng.normal(0.0, 0.7, size=n)\nprobs = 1.0 / (1.0 + np.exp(-logits))\ny = rng.binomial(1, probs)\n\nnames = [\"is_high_risk_bin (TRUE)\", \"txn_velocity (TRUE)\", \"random_noise_float (NOISE)\", \"random_uuid_int (NOISE)\"]\nX = np.column_stack([is_high_risk_bin, txn_velocity, random_noise_float, random_uuid_int])\nX_tr, X_val, y_tr, y_val = train_test_split(X, y, test_size=0.35, stratify=y, random_state=42)\n\n# RF default (min_samples_leaf=1 -> pohon dalam yang agresif mengeksploitasi fitur kontinu/UUID!)\nrf = RandomForestClassifier(n_estimators=120, min_samples_leaf=1, random_state=42, n_jobs=1).fit(X_tr, y_tr)\n\nmdi = rf.feature_importances_\npi_train = permutation_importance(rf, X_tr, y_tr, scoring=\"roc_auc\", n_repeats=10, random_state=42, n_jobs=1)\npi_val = permutation_importance(rf, X_val, y_val, scoring=\"roc_auc\", n_repeats=10, random_state=42, n_jobs=1)\n\nprint(f\"ROC-AUC Train = {roc_auc_score(y_tr, rf.predict_proba(X_tr)[:, 1]):.4f} | ROC-AUC Held-Out Val = {roc_auc_score(y_val, rf.predict_proba(X_val)[:, 1]):.4f}\")\nprint(\"\\n=== Perbandingan MDI vs Train-Permutation (JEBAKAN!) vs Held-Out Validation-Permutation ===\")\nprint(\"Fitur                       | MDI (.feature_imp_) | Permutasi TRAIN | Permutasi VAL (JUJUR)\")\nprint(\"-\" * 92)\nfor nm, m_val, pt_m, pv_m, pv_s in zip(\n    names, mdi, pi_train.importances_mean, pi_val.importances_mean, pi_val.importances_std\n):\n    print(f\"{nm:27s} | {m_val:19.4f} | {pt_m:15.4f} | {pv_m:+10.4f} +/- {pv_s:.4f}\")\n\n# Buktikan dampak bisnis: pangkas ke top-2 fitur menurut MDI vs top-2 menurut Val Permutation!\ntop2_mdi = np.argsort(mdi)[::-1][:2]\ntop2_val = np.argsort(pi_val.importances_mean)[::-1][:2]\nauc_mdi = roc_auc_score(y_val, RandomForestClassifier(n_estimators=120, random_state=42, n_jobs=1).fit(X_tr[:, top2_mdi], y_tr).predict_proba(X_val[:, top2_mdi])[:, 1])\nauc_val = roc_auc_score(y_val, RandomForestClassifier(n_estimators=120, random_state=42, n_jobs=1).fit(X_tr[:, top2_val], y_tr).predict_proba(X_val[:, top2_val])[:, 1])\nprint(\"-\" * 92)\nprint(f\"Top-2 pilihan MDI      : {[names[i] for i in top2_mdi]} -> Val ROC-AUC = {auc_mdi:.4f}\")\nprint(f\"Top-2 pilihan Val-Perm : {[names[i] for i in top2_val]} -> Val ROC-AUC = {auc_val:.4f}\")",
          "expectedOutput": "ROC-AUC Train = 1.0000 | ROC-AUC Held-Out Val = 0.6263\n\n=== Perbandingan MDI vs Train-Permutation (JEBAKAN!) vs Held-Out Validation-Permutation ===\nFitur                       | MDI (.feature_imp_) | Permutasi TRAIN | Permutasi VAL (JUJUR)\n--------------------------------------------------------------------------------------------\nis_high_risk_bin (TRUE)     |              0.0757 |          0.1258 |    +0.0550 +/- 0.0230\ntxn_velocity (TRUE)         |              0.3802 |          0.3043 |    +0.0700 +/- 0.0181\nrandom_noise_float (NOISE)  |              0.2674 |          0.1099 |    -0.0232 +/- 0.0182\nrandom_uuid_int (NOISE)     |              0.2767 |          0.1191 |    -0.0092 +/- 0.0135\n--------------------------------------------------------------------------------------------\nTop-2 pilihan MDI      : ['txn_velocity (TRUE)', 'random_uuid_int (NOISE)'] -> Val ROC-AUC = 0.5781\nTop-2 pilihan Val-Perm : ['txn_velocity (TRUE)', 'is_high_risk_bin (TRUE)'] -> Val ROC-AUC = 0.6335",
          "actualOutput": "ROC-AUC Train = 1.0000 | ROC-AUC Held-Out Val = 0.6263\n\n=== Perbandingan MDI vs Train-Permutation (JEBAKAN!) vs Held-Out Validation-Permutation ===\nFitur                       | MDI (.feature_imp_) | Permutasi TRAIN | Permutasi VAL (JUJUR)\n--------------------------------------------------------------------------------------------\nis_high_risk_bin (TRUE)     |              0.0757 |          0.1258 |    +0.0550 +/- 0.0230\ntxn_velocity (TRUE)         |              0.3802 |          0.3043 |    +0.0700 +/- 0.0181\nrandom_noise_float (NOISE)  |              0.2674 |          0.1099 |    -0.0232 +/- 0.0182\nrandom_uuid_int (NOISE)     |              0.2767 |          0.1191 |    -0.0092 +/- 0.0135\n--------------------------------------------------------------------------------------------\nTop-2 pilihan MDI      : ['txn_velocity (TRUE)', 'random_uuid_int (NOISE)'] -> Val ROC-AUC = 0.5781\nTop-2 pilihan Val-Perm : ['txn_velocity (TRUE)', 'is_high_risk_bin (TRUE)'] -> Val ROC-AUC = 0.6335",
