          "id": "code-ml-14-4-ch14_4_diag",
          "title": "Audit Produksi: Dilusi Multikolinearitas (3 Kembaran) + Mitigasi Grouped Perm & Spearman Ward Clustering",
          "language": "python",
          "filename": "14_4_multicollinearity_dilution_spearman_ward.py",
          "code": "import numpy as np\nfrom scipy.cluster import hierarchy\nfrom scipy.spatial.distance import squareform\nfrom scipy.stats import spearmanr\nfrom sklearn.ensemble import RandomForestRegressor\nfrom sklearn.inspection import permutation_importance\nfrom sklearn.metrics import r2_score\nfrom sklearn.model_selection import train_test_split\n\nrng = np.random.default_rng(152)\nn = 900\n\n# 1 fitur terkuat (gross_amount) memiliki 2 kembaran multikolinear (net_amount, taxed_amount; r > 0.99)!\n# Plus 1 fitur independen menengah (tenure_months) dan 1 fitur noise murni (random_session_id)\ngross = rng.normal(0.0, 1.0, size=n)\nnet = gross + rng.normal(0.0, 0.06, size=n)\ntaxed = gross * 1.11 + rng.normal(0.0, 0.06, size=n)\ntenure = rng.normal(0.0, 1.0, size=n)\nnoise_id = rng.integers(10_000, 999_999, size=n).astype(float)\n\n# Sinyal sejati: 80% varians berasal dari klaster gross/net/taxed, hanya 20% dari tenure!\ny = 3.0 * gross + 1.5 * tenure + rng.normal(0.0, 0.7, size=n)\n\nfeat_names = [\"gross_amount\", \"net_amount\", \"taxed_amount\", \"tenure_months\", \"random_session_id\"]\nX = np.column_stack([gross, net, taxed, tenure, noise_id])\nX_tr, X_val, y_tr, y_val = train_test_split(X, y, test_size=0.35, random_state=42)\n\nrf_all = RandomForestRegressor(n_estimators=100, min_samples_leaf=3, random_state=42, n_jobs=1).fit(X_tr, y_tr)\nbase_r2 = float(r2_score(y_val, rf_all.predict(X_val)))\npi_single = permutation_importance(rf_all, X_val, y_val, scoring=\"r2\", n_repeats=12, random_state=42, n_jobs=1)\n\nprint(\"=== 1. Efek Dilution Multikolinearitas: Fitur Terkuat Terlihat Lemah di Single Permutation ===\")\nprint(\"Fitur             | MDI    | Single Perm Val R2 | Diagnosis\")\nprint(\"-\" * 74)\nfor nm, m, p in zip(feat_names, rf_all.feature_importances_, pi_single.importances_mean):\n    diag = \"TERDILUSI! (kembaran menolong)\" if nm in (\"gross_amount\", \"net_amount\", \"taxed_amount\") else (\"Sinyal mandiri\" if nm == \"tenure_months\" else \"Noise (aman = 0)\")\n    print(f\"{nm:17s} | {m:6.3f} | {p:18.4f} | {diag}\")\n\n# 2. Mitigasi A: Group / Clustered Permutation (acak ketiga fitur kembar SERENTAK!)\nr_grp = np.random.default_rng(42)\ngrp_drops = []\nfor _ in range(12):\n    Xp = X_val.copy()\n    perm_idx = r_grp.permutation(len(y_val))\n    Xp[:, [0, 1, 2]] = X_val[perm_idx][:, [0, 1, 2]]\n    grp_drops.append(base_r2 - float(r2_score(y_val, rf_all.predict(Xp))))\nprint(f\"\\n=== 2. Mitigasi A — Grouped Permutation Klaster [gross, net, taxed] Serentak ===\")\nprint(f\"Drop R2 Saat Diacak Serentak: {float(np.mean(grp_drops)):.4f} (kekuatan sejati terungkap utuh!)\")\n\n# 3. Mitigasi B: Spearman Rank Correlation + Ward Hierarchical Clustering (Standar Scikit-Learn)\ncorr = spearmanr(X_tr).statistic\ncorr = 0.5 * (corr + corr.T)\ndist = np.clip(1.0 - np.abs(corr), 0.0, 1.0)\nnp.fill_diagonal(dist, 0.0)\nlinkage = hierarchy.ward(squareform(dist))\ncluster_ids = hierarchy.fcluster(linkage, t=0.25, criterion=\"distance\")\n\n# Pilih 1 wakil per klaster (indeks pertama) lalu hitung ulang Permutation Importance pada model bersih\nselected_idx = []\nfor cid in np.unique(cluster_ids):\n    members = np.where(cluster_ids == cid)[0]\n    selected_idx.append(int(members[0]))\nselected_idx.sort()\n\nrf_dedup = RandomForestRegressor(n_estimators=100, min_samples_leaf=3, random_state=42, n_jobs=1).fit(X_tr[:, selected_idx], y_tr)\npi_dedup = permutation_importance(rf_dedup, X_val[:, selected_idx], y_val, scoring=\"r2\", n_repeats=12, random_state=42, n_jobs=1)\nr2_dedup = float(r2_score(y_val, rf_dedup.predict(X_val[:, selected_idx])))\n\nprint(f\"\\n=== 3. Mitigasi B — Spearman Ward Clustering (t=0.25) -> Wakil Klaster & Re-fit ===\")\nprint(f\"Klaster ID per fitur : {dict(zip(feat_names, [int(c) for c in cluster_ids]))}\")\nprint(f\"R2 Val Sebelum ({len(feat_names)} fitur) = {base_r2:.4f} | Sesudah Deduplikasi ({len(selected_idx)} fitur) = {r2_dedup:.4f}\")\nfor idx_local, orig_i in enumerate(selected_idx):\n    print(f\"  Wakil '{feat_names[orig_i]:17s}' -> Val Permutation R2 = {pi_dedup.importances_mean[idx_local]:+.4f}\")",
